mapper.select:
SELECT  FROM access_clean_execution_log
WHERE stats_pull_task_id = #{statsPullTaskId}
  AND channel_code = #{channelCode}
  AND coverage_day = #{coverageDay}
  AND (config_snapshot_json IS NULL OR config_snapshot_json NOT LIKE '%"logType":"BATCH_SUMMARY"%')
ORDER BY id DESC
LIMIT 1

SELECT  FROM access_clean_execution_log

ORDER BY COALESCE(coverage_day, execution_date) DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE access_clean_execution_log el SET
    total_scanned = (
        SELECT COUNT(*) FROM access_clean_package_item i
        WHERE JSON_CONTAINS(el.config_snapshot_json, CAST(i.last_run_id AS JSON), '$.lastRunId')
    )
WHERE el.id = #{executionLogId}
